// Reads the form: the page to check and how many of its links to look at.
const form = $input.first().json;
let address = String(form.address || '').trim();
const asked = Number(form.links);
const max = Number.isInteger(asked) && asked >= 1 ? Math.min(asked, 50) : 30;

const fail = (error) => [{ json: { ok: false, error } }];
if (!address || /\s/.test(address)) return fail('Type the address of a web page, for example https://example.com/blog/post.');
// A backslash is read as a slash by browsers and by many HTTP clients, so a host could hide before it: refuse it.
if (address.indexOf('\\') >= 0) return fail('Type the address with forward slashes only, for example https://example.com/blog/post.');
if (address.indexOf('://') < 0) address = 'https://' + address;
if (!/^https?:\/\//i.test(address)) return fail('Only http and https addresses can be checked.');

// The host is read by cutting the text, not with the URL class, which this editor does not have.
let host = address.slice(address.indexOf('//') + 2);
let end = host.length;
for (const mark of ['/', '?', '#']) {
  const at = host.indexOf(mark);
  if (at >= 0 && at < end) end = at;
}
host = host.slice(0, end);
if (host.indexOf('@') >= 0) host = host.slice(host.lastIndexOf('@') + 1);
let port = '';
if (host.indexOf(':') > 0) {
  port = host.slice(host.lastIndexOf(':') + 1);
  host = host.slice(0, host.lastIndexOf(':'));
}
// Look-alike forms of letters (full-width, mathematical) are read as the plain letters, as the HTTP client will read them.
host = host.normalize('NFKC').toLowerCase().replace(/\.$/, '');

// Only a name that looks public is accepted: letters in the last part, so no IP numbers in any notation, no one-word names, no
// local names. A name that points to a private address cannot be told from a public one here.
const LOCAL = ['localhost', 'local', 'internal', 'lan', 'home', 'corp', 'intranet', 'test', 'invalid', 'svc', 'localdomain', 'private', 'cluster', 'arpa', 'docker'];
const labels = host.split('.');
const last = labels[labels.length - 1];
if (!/^[\p{L}\p{M}\p{N}_\u200c\u200d-]+(\.[\p{L}\p{M}\p{N}_\u200c\u200d-]+)+$/u.test(host) || !/^([\p{L}\p{M}]{2,}|xn--[a-z0-9-]+)$/u.test(last) || LOCAL.includes(last)) {
  return fail('That address is not a public web site. Only public web pages can be checked.');
}
if (port && !['80', '443', '8080', '8443'].includes(port)) return fail('Only the usual web ports (80, 443, 8080 and 8443) can be checked.');

return [{ json: { ok: true, url: address, max } }];

// The page may answer with a redirect. One redirect is followed, and only to a name that looks public, so that the page is never
// sent anywhere unchecked. The answer goes on as it is, with the address to ask next (or none).
const request = $('Check the request').first().json;
const res = $input.first().json;

const sameUrl = (a, b) => a.split('#')[0] === b.split('#')[0];
const pathOf = (u) => {
  const rest = u.slice(u.indexOf('//') + 2);
  const slash = rest.indexOf('/');
  return slash < 0 ? '' : rest.slice(slash).split('#')[0].split('?')[0];
};
// "." and ".." segments of a path are resolved; the query stays as it is.
const dotted = (p) => {
  const cut = p.search(/[?#]/);
  const path = cut < 0 ? p : p.slice(0, cut);
  const rest = cut < 0 ? '' : p.slice(cut);
  const out = [];
  for (const seg of path.split('/')) {
    if (seg === '..') { if (out.length > 1) out.pop(); } else if (seg !== '.') out.push(seg);
  }
  return out.join('/') + rest;
};
const resolveLocation = (from, loc) => {
  const l = String(loc).trim();
  if (/^https?:\/\//i.test(l)) return l;
  const scheme = from.slice(0, from.indexOf(':'));
  if (l.startsWith('//')) return scheme + ':' + l;
  const rest = from.slice(from.indexOf('//') + 2);
  const cut = rest.search(/[\/?#]/);
  const origin = scheme + '://' + (cut < 0 ? rest : rest.slice(0, cut));
  if (l.startsWith('/')) return origin + dotted(l);
  if (l.startsWith('?')) return origin + (pathOf(from) || '/') + l;
  if (l.startsWith('#')) return from.split('#')[0];
  const dir = pathOf(from).slice(0, pathOf(from).lastIndexOf('/') + 1) || '/';
  return origin + dotted(dir + l);
};
const authority = (u) => {
  let h = u.slice(u.indexOf('//') + 2);
  let end = h.length;
  for (const mark of ['/', '?', '#']) { const at = h.indexOf(mark); if (at >= 0 && at < end) end = at; }
  h = h.slice(0, end);
  if (h.indexOf('@') >= 0) h = h.slice(h.lastIndexOf('@') + 1);
  // Look-alike forms of letters (full-width, mathematical) are read as the plain letters, as the HTTP client will read them.
  return h.normalize('NFKC').toLowerCase();
};
