const portOf = (u) => { const a = authority(u); const i = a.lastIndexOf(':'); return i > 0 ? a.slice(i + 1) : ''; };
// A name that looks public (letters in its last part: no IP numbers in any notation, no local names) on a usual web port.
const LOCAL = ['localhost', 'local', 'internal', 'lan', 'home', 'corp', 'intranet', 'test', 'invalid', 'svc', 'localdomain', 'private', 'cluster', 'arpa', 'docker'];
const reachable = (u) => {
  const h = hostOf(u);
  const last = h.slice(h.lastIndexOf('.') + 1);
  return u.indexOf('\\') < 0 && /^[\p{L}\p{M}\p{N}_\u200c\u200d-]+(\.[\p{L}\p{M}\p{N}_\u200c\u200d-]+)+$/u.test(h) && /^([\p{L}\p{M}]{2,}|xn--[a-z0-9-]+)$/u.test(last) && !LOCAL.includes(last) && ['', '80', '443', '8080', '8443'].includes(portOf(u));
};

let next = '';
const status = Number(res.statusCode) || 0;
const location = res.headers && res.headers.location;
if ([301, 302, 303, 307, 308].includes(status) && location) {
  const target = resolveLocation(request.url, location);
  if (reachable(target) && !sameUrl(target, request.url)) next = target;
}
return [{ json: Object.assign({}, res, { next }) }];

// Collects the links of the page, resolves them against the page address and keeps at most the number asked for.
