const status = Number(res.statusCode) || 200;
if (status >= 300 && status < 400) {
  const where = String((res.headers && res.headers.location) || '').replace(/\s+/g, ' ').slice(0, 200);
  return fail('The page redirects' + (where ? ' to ' + where : '') + '. Only one redirect, to a public address, is followed, so type the address that it finally leads to.');
}
if (status >= 400) return fail('The page answered HTTP ' + status + ', so there are no links to check.');
const html = String(res.data || '');
if (!html.trim()) return fail('The page is empty.');

// Character references: the common named ones, and numbers (an old page may write a number from the Windows code page, such as &#146;).
const NAMED = {
  amp: '&', quot: '"', apos: "'", lt: '<', gt: '>', nbsp: ' ', mdash: '-', ndash: '-', rsquo: '\u2019', lsquo: '\u2018', ldquo: '\u201c', rdquo: '\u201d',
