  if (e[0] === '#') {
    const n = e[1] === 'x' || e[1] === 'X' ? parseInt(e.slice(2), 16) : Number(e.slice(1));
    const c = WINDOWS[n] || n;
    return c > 0 && c < 0x110000 ? String.fromCodePoint(c) : ' ';
  }
  const v = NAMED[e.toLowerCase()];
  return v === undefined ? m : v;
});
