const oneLine = (s) => decode(String(s).replace(/<[^<>]*>/g, ' ')).replace(/[\u0001-\u001f\u007f-\u009f\u200b\u200e\u200f\u202a-\u202e\u2060-\u206f\ufeff]/g, ' ').replace(/\s+/g, ' ').trim();

// Comments, scripts, styles and templates are not links of the page, even when they hold text that looks like one.
// A lower-case copy of the page, letter by letter so that every position still matches (a letter such as "I with a dot" would
// change the length of the whole text), is what the tags are searched in.
const low = Array.from(html, (ch) => { const l = ch.toLowerCase(); return l.length === ch.length ? l : ch; }).join('');
const SKIP = [['<!--', '-->'], ['<script', '</script'], ['<style', '</style'], ['<template', '</template']];
const markup = (() => {
  const next = SKIP.map(() => -2);
  let out = '';
  let from = 0;
  while (from < html.length) {
    let best = -1;
    let kind = null;
    SKIP.forEach((k, i) => {
      if (next[i] !== -1 && next[i] < from) next[i] = low.indexOf(k[0], from);
      if (next[i] >= 0 && (best < 0 || next[i] < best)) { best = next[i]; kind = k; }
    });
    if (best < 0) break;
    const after = best + kind[0].length;
    const isComment = kind[0] === '<!--';
    // An opening tag has the whole name ("<script>", "<script src=...>", not "<scripts>").
    if (!isComment && !/[\s>\/]/.test(html.charAt(after))) { out += html.slice(from, after); from = after; continue; }
    // A closing tag has the whole name too ("</script>", not "</scripts-element>").
    let close = low.indexOf(kind[1], after);
    while (!isComment && close >= 0 && !/[\s>\/]/.test(html.charAt(close + kind[1].length))) close = low.indexOf(kind[1], close + kind[1].length);
    if (close < 0) {
      // A comment that is never closed runs to the end of the page; a tag that is never closed is just text (it may sit in an attribute).
      if (isComment) { out += html.slice(from, best); from = html.length; break; }
      out += html.slice(from, after);
      from = after;
      continue;
    }
    out += html.slice(from, best);
    from = close + kind[1].length;
  }
  return out + html.slice(from);
})();

