  return h.slice(0, end).toLowerCase();
};
// A front page has no path and no query. The words of the host name (the name of the site) are not the name of the page.
const isFront = (u) => {
  const rest = String(u).slice(String(u).indexOf('//') + 2).split('#')[0];
  return rest.indexOf('?') < 0 && rest.split('/').filter(Boolean).length <= 1;
};
const siteWords = new Set((hostOf(rec.url) + '.' + hostOf(rec.target)).split(/[^a-z0-9]+/).filter((w) => w.length > 3));
const wordSet = (s) => new Set(norm(s).split(' ').filter((w) => w.length > 3 && !siteWords.has(w)));
const overlap = (a, b) => {
  const A = wordSet(a);
  const B = wordSet(b);
  if (!A.size) return 0;
  let n = 0;
  for (const w of A) if (B.has(w)) n += 1;
  return n / A.size;
};

const out = Object.assign({}, rec);
const said = answer.error ? String((answer.error.code || '') + ' ' + (answer.error.message || answer.error)) : '';
const unverified = (why) => {
  out.kind = 'redirect-unverified';
  out.detail = 'It redirects to ' + rec.target + ', ' + why + ' Check it by hand.';
  out.search = false;
};
const lost = (what) => {
  out.kind = 'leads-elsewhere';
  out.detail = 'It redirects to ' + rec.target + ', ' + what + ' The page it used to be, "' + rec.oldTitle.slice(0, 80) + '", is not there.';
  out.search = rec.phraseOk;
};
// A deep page that now leads to the front page of its site has lost its page, whatever the front page says or does next.
const toFront = isFront(rec.target) && !isFront(rec.url);
if (answer.error ? /ENOTFOUND/.test(said) : status === 404 || status === 410) {
  out.kind = 'dead';
  out.detail = 'It redirects to ' + rec.target + ', which does not answer either' + (status ? ' (HTTP ' + status + ')' : '') + '.';
  out.search = rec.phraseOk;
} else if (rec.wallTitle) {
  unverified('and what the archive kept of the old page is an error, parking or move notice, so there is nothing to compare with.');
} else if (answer.error || !status || status >= 400) {
  // A refusal, an error or a timeout says nothing about the page, so it is not called gone.
  unverified('which did not give a page to compare with' + (status ? ' (HTTP ' + status + ').' : '.'));
} else if (status >= 300) {
  // This request does not follow redirects, so a chain is not walked blindly.
  if (toFront) lost('the front page of the site, which then redirects again.');
  else unverified('which redirects again.');
} else if (/just a moment|attention required|access denied|are you a robot|captcha|verify you are/i.test(names[0] || '')) {
  if (toFront) lost('the front page of the site, which answered with a robot check.');
  else unverified('which answered with a robot check.');
} else if (!names.length) {
  if (toFront) lost('the front page of the site, which has no title.');
  else unverified('which has no title to compare with.');
} else if (!toFront && wordSet(rec.oldTitle).size === 0) {
  unverified('but the old title has too few long words to compare with the new one.');
} else {
  const same = toFront ? 0 : Math.max(0, ...names.map((n) => overlap(rec.oldTitle, n)));
  out.newTitle = names[0].slice(0, 120);
  if (same >= 0.34) {
    out.kind = 'moved';
    out.detail = 'It has moved to ' + rec.target + ' and the page is still called "' + out.newTitle.slice(0, 80) + '".';
    out.search = false;
  } else {
    lost('a page called "' + out.newTitle.slice(0, 80) + '".');
  }
}
return [{ json: out }];

// Decides which search result, if any, is the page that was linked. The old name must be the page's own title, or - for a page on
// the same site - nearly all of its words must be. A page that only mentions the name in its text, such as a list, is never offered.
const rec = $('Worth a search?').first().json;
const results = $input.all().map((i) => i.json);
const pageUrl = $('Collect the links').first().json.page;

// Letters are compared without accents and case.
const norm = (s) => String(s || '').normalize('NFKD').replace(/[\u0300-\u036f]/g, '').toLowerCase().replace(/[^\p{L}\p{N}]+/gu, ' ').trim();
const hostOf = (u) => {
  let h = String(u).slice(String(u).indexOf('//') + 2);
  let end = h.length;
  for (const mark of ['/', '?', '#']) { const at = h.indexOf(mark); if (at >= 0 && at < end) end = at; }
  h = h.slice(0, end);
  if (h.indexOf(':') > 0) h = h.slice(0, h.lastIndexOf(':'));
  return h.toLowerCase().replace(/^www\./, '');
};
// Two labels make a site, three where the second one is a public suffix (co.uk) or the host gives out names to many people (blogspot.com).
const SECOND = ['co', 'com', 'org', 'net', 'ac', 'gov', 'edu', 'or', 'ne', 'go'];
const SHARED = ['blogspot.com', 'github.io', 'gitlab.io', 'wordpress.com', 'substack.com', 'medium.com', 'tumblr.com', 'wixsite.com', 'weebly.com', 'netlify.app', 'vercel.app', 'pages.dev', 'herokuapp.com', 'fandom.com', 'webflow.io', 'carrd.co', 'sites.google.com'];
const site = (u) => {
  const parts = hostOf(u).split('.');
  const n = (parts.length > 2 && SECOND.includes(parts[parts.length - 2])) || SHARED.includes(parts.slice(-2).join('.')) ? 3 : 2;
  return parts.slice(-n).join('.');
};
const same = (a, b) => String(a).split('#')[0].replace(/^https?:\/\/(www\.)?/i, '').replace(/\/+$/, '').toLowerCase() === String(b).split('#')[0].replace(/^https?:\/\/(www\.)?/i, '').replace(/\/+$/, '').toLowerCase();

// An address with no path and no query is a front page; a query (such as ?p=73) names a page.
const isFront = (u) => {
  const rest = String(u).slice(String(u).indexOf('//') + 2).split('#')[0];
  return rest.indexOf('?') < 0 && rest.split('/').filter(Boolean).length <= 1;
};

const out = Object.assign({}, rec, { replacement: null, mentions: [], searchNote: '' });
const failure = results.find((r) => r.error);
const real = results.filter((r) => r.url && !r.error);
if (!real.length) {
  out.searchNote = failure && /challenge|rate limit|blocked|not sent/i.test(String(failure.error))
    ? 'DuckDuckGo did not answer (it limits how often one address may search), so this link was not searched for.'
    : 'The search returned no pages.';
  return [{ json: out }];
}

const phrase = norm(rec.phrase);
const phraseWords = phrase.split(' ');
const words = phraseWords.filter((w) => w.length > 3);
// Whole words only: "protocol" is not inside "protocols".
const holds = (text, part) => (' ' + text + ' ').indexOf(' ' + part + ' ') >= 0;
const found = [];
for (const r of real) {
  const url = String(r.url);
  if (/web\.archive\.org|archive\.(is|today|ph)|wikipedia\.org/i.test(url)) continue;
  if (same(url, rec.url) || same(url, pageUrl)) continue;
  // A page that the search found but that did not load as a page (the node says why) is not a replacement.
  if (/\b(404|410)\b/.test(String(r.pageContentError || ''))) continue;
  // A site's front page is not the page that was linked, whatever its title says, unless the link was a front page too.
  if (isFront(url) && !isFront(rec.url)) continue;
  const names = [r.pageTitle, r.title].map(norm).filter(Boolean);
  // The old name must be most of the new title. A name that is only the site's own name sits inside every title of that site.
  const own = names.some((n) => holds(n, phrase) && phraseWords.length / n.split(' ').length >= 0.4);
  const ratio = Math.max(0, ...names.map((n) => {
    const set = new Set(n.split(' '));
    return words.length ? words.filter((w) => set.has(w)).length / words.length : 0;
  }));
  const sameSite = site(url) === site(rec.url);
  let verdict = 'none';
  if (own) verdict = 'verified';
  else if (sameSite && words.length >= 3 && ratio >= 0.75) verdict = 'likely';
  else if (holds(norm(r.pageContent), phrase)) verdict = 'mention';
  if (verdict !== 'none') found.push({ url, title: String(r.pageTitle || r.title || '').slice(0, 120), verdict, sameSite });
}
const rank = (c) => (c.verdict === 'verified' && c.sameSite ? 0 : c.verdict === 'verified' ? 1 : c.verdict === 'likely' ? 2 : 3);
found.sort((a, b) => rank(a) - rank(b));
const best = found.find((c) => c.verdict !== 'mention');
if (best) {
  out.replacement = {
    url: best.url,
    title: best.title,
    verdict: best.verdict,
    relation: best.sameSite ? 'same site' : 'another site',
  };
}
out.mentions = found.filter((c) => c.verdict === 'mention').slice(0, 2).map((c) => ({ url: c.url, title: c.title }));
if (!best) out.searchNote = out.mentions.length
  ? 'No page with this title was found. Some pages mention the title in their text, which does not make them the page.'
  : 'No page with this title was found.';
return [{ json: out }];

// Builds the page that is shown: a summary, then one row for every link that has a problem, with what is known about each.
// Everything that came from a web page is escaped; a link is made only for an http or https address.
const meta = $('Collect the links').first().json;
const rows = $input.all().map((i) => i.json).sort((a, b) => a.idx - b.idx);

const esc = (s) => String(s == null ? '' : s).replace(/[&<>"']/g, (c) => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' })[c]);
// The joiners U+200C and U+200D stay: some scripts need them inside words.
const oneLine = (s) => String(s == null ? '' : s).replace(/[\u0001-\u001f\u007f-\u009f\u200b\u200e\u200f\u202a-\u202e\u2060-\u206f\ufeff]/g, ' ').replace(/\s+/g, ' ').trim();
const link = (url, label) => (/^https?:\/\//i.test(String(url)) && String(url).length <= 2000 ? '<a href="' + esc(String(url).split(' ').join('%20')) + '" target="_blank" rel="noopener noreferrer">' + esc(oneLine(label || url).slice(0, 140)) + '</a>' : esc(oneLine(label || url).slice(0, 140)));

const works = rows.filter((r) => r.kind === 'ok' || r.kind === 'moved');
const broken = rows.filter((r) => r.kind === 'dead');
const elsewhere = rows.filter((r) => r.kind === 'leads-elsewhere');
const byHand = rows.filter((r) => r.kind === 'redirect' || r.kind === 'redirect-unverified');
const unknown = rows.filter((r) => r.kind === 'unknown');
const problems = [].concat(broken, elsewhere, byHand, unknown);

const LABEL = { dead: 'Broken', 'leads-elsewhere': 'Leads somewhere else now', redirect: 'Redirects, not compared', 'redirect-unverified': 'Redirects, not compared', unknown: 'Could not be checked' };

// Past the limit of 12, a broken link or a redirect that loses the page is not looked into at all.
const notLooked = (r) => (r.kind === 'dead' || r.kind === 'redirect') && !r.look;
const copyCell = (r) => {
  if (r.kind === 'unknown' || notLooked(r)) return '<span class="muted">-</span>';
  if (r.replayUrl) return link(r.replayUrl, 'Saved ' + r.copyDate) + '<br><span class="muted">as the Wayback Machine kept it</span>';
  if (r.copyFailed) return '<span class="muted">The Wayback Machine did not answer, so it is not known whether there is one.</span>';
  return '<span class="muted">No saved copy found</span>';
};
const replacementCell = (r) => {
  if (notLooked(r)) return '<span class="muted">Not looked into: only the first 12 problems are.</span>';
  if (r.replacement) {
    const rep = r.replacement;
    const how = rep.verdict === 'verified'
      ? (rep.relation === 'same site' ? 'On the same site. Its own title contains the old title.' : 'On another site, with the same title. It may be a copy of the page or a page about it.')
      : 'On the same site. Its title shares nearly all the words of the old one.';
    return (rep.verdict === 'verified' ? '' : '<strong>Possible: </strong>') + link(rep.url, rep.title || rep.url) + '<br><span class="muted">' + esc(how) + '</span>';
  }
  if (r.kind === 'unknown') return '<span class="muted">-</span>';
  if (r.searchNote) return '<span class="muted">' + esc(r.searchNote) + '</span>';
  if (r.kind === 'redirect' || r.kind === 'redirect-unverified') return '<span class="muted">Not searched.</span>';
  if (r.copyFailed) return '<span class="muted">Not searched: without a saved copy there is no old title to look for.</span>';
  if (!r.copyUrl) return '<span class="muted">Not searched: with no saved copy there is no old title to look for.</span>';
  if (!r.phraseOk) return '<span class="muted">Not searched: the old title ("' + esc(oneLine(r.oldTitle).slice(0, 60)) + '") is too general to find one page.</span>';
  return '<span class="muted">Not searched.</span>';
};

const tableRows = problems.map((r) => '<tr><td>' + esc(oneLine(r.text)) + '<br><span class="url">' + link(r.url, r.url) + '</span></td>'
  + '<td><strong>' + esc(LABEL[r.kind] || r.kind) + '</strong><br>' + esc(oneLine(r.detail)) + (r.oldTitle ? '<br><span class="muted">It used to be called "' + esc(oneLine(r.oldTitle).slice(0, 90)) + '".</span>' : '') + '</td>'
  + '<td>' + copyCell(r) + '</td><td>' + replacementCell(r) + '</td></tr>').join('');

const fixes = problems.filter((r) => r.replacement && r.replacement.verdict === 'verified').length;
const copies = problems.filter((r) => r.replayUrl && !r.replacement).length;
const notes = [];
if (meta.found > meta.checked) notes.push('The page has ' + meta.found + ' links to other pages; the first ' + meta.checked + ' were checked.');
if (meta.skippedPrivate) notes.push(meta.skippedPrivate + ' link(s) to private or local addresses, or to ports other than 80, 443, 8080 and 8443, were left out.');
if (meta.skippedSocial) notes.push(meta.skippedSocial + ' link(s) to sites that turn away automatic checks (social networks and the Wayback Machine itself) were left out.');

const html = '<h1>Link check</h1>'
  + '<p>Page: ' + link(meta.page, meta.page) + '<br>' + esc(String(meta.checked)) + ' links checked.</p>'
  + '<p class="summary"><strong>' + works.length + '</strong> work &middot; <strong>' + broken.length + '</strong> broken &middot; <strong>' + elsewhere.length + '</strong> lead somewhere else now &middot; <strong>' + (byHand.length + unknown.length) + '</strong> need a look by hand</p>'
  + (problems.length
    ? '<p>' + (fixes ? fixes + ' link(s) have a replacement that the code could verify. ' : 'No replacement could be verified. ') + (copies ? copies + ' more have a saved copy to link to instead.' : '') + '</p>'
      + '<table><thead><tr><th>Link</th><th>Problem</th><th>Saved copy</th><th>Replacement</th></tr></thead><tbody>' + tableRows + '</tbody></table>'
    : '<p>Every link that could be checked works.</p>')
  + (notes.length ? '<p class="muted">' + notes.map(esc).join(' ') + '</p>' : '')
  + '<h2>How to read this</h2>'
  + '<p class="muted">A link is <em>broken</em> when its server says the page is gone, the domain does not exist, or the page itself says it was not found. A link <em>leads somewhere else</em> when it redirects to a page that is no longer the page that was linked: the saved copy and the new page share too few words in their titles. A <em>saved copy</em> is what the Wayback Machine kept of the page. A <em>replacement</em> is shown as verified only when the title of a search result contains the old title; it proves that the title is the same, not that the text is, and a short common title can belong to another page, so open a replacement before you use it. A link that redirects to an address that keeps the name of the page counts as working: the new address is not asked. Nothing here has been changed on your page.</p>';

return [{ json: { html, problems: problems.length, fixes } }];

// The page shown when there is nothing to check: the address was not accepted, the page could not be read, or it has no links.
const item = $input.first().json;
const esc = (s) => String(s == null ? '' : s).replace(/[&<>"']/g, (c) => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' })[c]);
const reason = String(item.error || 'Nothing could be checked.').replace(/\s+/g, ' ').slice(0, 300);
const html = '<h1>Nothing to check</h1><p>' + esc(reason) + '</p>'
  + '<p class="muted">Type the address of a public web page that has links in it. Pages that build their links with JavaScript show none in the page source, and the check reads only the source.</p>';
return [{ json: { html } }];
